def compute(vars):
    old_salary = vars["v1"]
    new_salary = vars["v2"]

    if old_salary == 0:
        return {
            "value": None,
            "trace": {
                "old_salary": old_salary,
                "new_salary": new_salary,
                "output_meta": {
                    "currency": None,
                    "scale": None,
                    "unit": "percentage"
                }
            }
        }

    change_ratio = (new_salary - old_salary) / old_salary
    percentage_increase = change_ratio * 100

    return {
        "value": percentage_increase,
        "trace": {
            "old_salary": old_salary,
            "new_salary": new_salary,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
